        HEXADECIMAL
        BYTES_PER_PIXEL = 3

        # The RGB bytes of a frame buffer of pixels 0-511, as a binary String; a pixel past 511 raises ArgumentError.
        # One lookup and one join for the whole frame: the simplest of the strategies plan 16 measured, and steady with
        # and without a JIT.
        def self.rgb(frame_buffer)
          rgb = COLOURS.values_at(*frame_buffer).join
          return rgb if rgb.bytesize == frame_buffer.size * BYTES_PER_PIXEL

          raise ArgumentError, "a pixel is outside 0-#{COLOURS.size - 1}"
        end
      end
    end
